const tabId = 1962625075;

const reviewData = await browserjs(tabId, () => {
  // Look for rating stars, review score, review count
  const ratingSection = document.querySelector('[data-testid*="review" i], [id*="review" i], [class*="review" i]');

  // Search for rating numbers
  const ratingRegex = /(\d(\.\d)?)\s*(out of|\/)\s*5/i;
  const ratingMatches = [];

  for (const el of document.querySelectorAll('*')) {
    if (el.children.length === 0) {
      const t = el.textContent.trim();
      const aria = el.getAttribute('aria-label');
      if (ratingRegex.test(t)) ratingMatches.push({ type: 'text', val: t });
      if (aria && ratingRegex.test(aria)) ratingMatches.push({ type: 'aria', val: aria });
      if (/reviews?\b/i.test(t) && /\d/.test(t)) ratingMatches.push({ type: 'review-count', val: t });
    }
  }

  // Also check if Bazarvoice or PowerReviews or Yotpo or native reviews are used
  const scriptTags = Array.from(document.querySelectorAll('script[type="application/ld+json"]')).map(s => {
    try {
      return JSON.parse(s.textContent);
    } catch(e) {
      return null;
    }
  }).filter(Boolean);

  return {
    ratingMatches,
    ldJson: scriptTags
  };
});

