const tabId = 1962625075;

const items = await browserjs(tabId, () => {
  // Find product cards. In earlier inspection:
  // Each product link had an href like backcountry.com/<brand-product-slug>
  // and parent containers with classes like 'css-j7qwjs', 'chakra-text', etc.

  // Let's find all product links on the page that correspond to product cards
  const links = Array.from(document.querySelectorAll('a[href]')).filter(a => {
    const href = a.href;
    return /https:\/\/www\.backcountry\.com\/[a-z0-9-]+$/i.test(href) &&
      !href.includes('/cat/') && !href.includes('/rc/') && !href.includes('/search') &&
      !href.includes('summit-club') && !href.includes('about') && !href.includes('accessibility') &&
      !href.includes('stores') && !href.includes('affiliates') && !href.includes('careers') &&
      !href.includes('privacy') && !href.includes('terms') && !href.includes('contact');
  });

  // For each link, let's look at its closest card container
  const results = [];
  const seenUrls = new Set();

  for (const a of links) {
    if (seenUrls.has(a.href)) continue;

    // Find the enclosing card container (travel up until a container with image, title, price)
    let card = a;
    for (let i = 0; i < 8; i++) {
      if (!card.parentElement || card.parentElement.tagName === 'BODY' || card.parentElement.tagName === 'MAIN') break;
      if (card.querySelector('img') && (card.textContent.includes('$') || card.textContent.includes('Sale'))) {
        // card found
        break;
      }
      card = card.parentElement;
    }

    const cardText = card.textContent.trim().replace(/\s+/g, ' ');
    if (!cardText.includes('$')) continue;

    seenUrls.add(a.href);

    // Extract all text lines or parts
    results.push({
      url: a.href,
      cardText: cardText,
      innerHtmlSnippet: card.innerHTML.slice(0, 300)
    });
  }

  return results;
});

console.log(`Found ${items.length} items`);
for (let i = 0; i < items.length; i++) {
  console.log(`\n--- Item ${i+1} ---`);
  console.log("URL:", items[i].url);
  console.log("Text:", items[i].cardText);
}

