const tabId = 1962625075;

const productDetails = await browserjs(tabId, () => {
  // Title
  const title = document.querySelector('h1')?.textContent?.trim();
  const brand = document.querySelector('[data-testid="product-brand"], [class*="brand" i]')?.textContent?.trim();

  // Rating and reviews
  const ratingEl = document.querySelector('[class*="rating" i], [data-testid*="rating" i], [aria-label*="star" i], [aria-label*="rating" i]');
  const ratingText = ratingEl?.getAttribute('aria-label') || ratingEl?.textContent?.trim();

  // All elements containing "star" or numbers out of 5
  const allStars = Array.from(document.querySelectorAll('*'))
    .filter(el => el.children.length === 0 && (el.textContent.includes('star') || el.getAttribute('aria-label')?.includes('star') || el.getAttribute('aria-label')?.includes('rating')))
    .map(el => ({ text: el.textContent.trim(), label: el.getAttribute('aria-label') }));

  // Price elements
  const prices = Array.from(document.querySelectorAll('[class*="price" i], [data-testid*="price" i]'))
    .map(el => el.textContent.trim().replace(/\s+/g, ' '));

  // Breadcrumbs
  const breadcrumbs = Array.from(document.querySelectorAll('nav[aria-label*="breadcrumb" i] li, [class*="breadcrumb" i] a'))
    .map(el => el.textContent.trim());

  // Tech specs / description
  const description = document.querySelector('[data-testid*="description"], [class*="description" i], #product-description')?.textContent?.trim().slice(0, 500);

  // Tech specs table or list
  const specs = Array.from(document.querySelectorAll('[class*="spec" i] tr, [class*="tech-spec" i] li, dl div')).map(el => el.textContent.trim().replace(/\s+/g, ' '));

  return {
    title,
    brand,
    ratingText,
    allStars,
    prices: Array.from(new Set(prices)),
    breadcrumbs,
    description,
    specs: specs.slice(0, 15)
  };
});

